CREATE TABLE "dealer_catalogs" ("id" TEXT NOT NULL PRIMARY KEY,"sellerId" TEXT NOT NULL,"name" TEXT NOT NULL,"brand" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"previousId" TEXT,"revision" INTEGER NOT NULL DEFAULT 1,"status" TEXT NOT NULL DEFAULT 'DRAFT',"dataset" TEXT NOT NULL,"approvedAt" DATETIME,"approvedHash" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "dealer_catalogs_previousId_key" ON "dealer_catalogs"("previousId");
CREATE INDEX "dealer_catalogs_sellerId_status_idx" ON "dealer_catalogs"("sellerId","status");
CREATE TABLE "catalog_checks" ("id" TEXT NOT NULL PRIMARY KEY,"catalogId" TEXT NOT NULL,"revision" INTEGER NOT NULL,"tableId" TEXT NOT NULL,"widthCm" REAL NOT NULL,"depthCm" REAL NOT NULL,"rule" TEXT NOT NULL,"expectedCents" INTEGER,"expectedReject" BOOLEAN NOT NULL,"actualCents" INTEGER,"passed" BOOLEAN NOT NULL,"message" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "catalog_checks_catalogId_fkey" FOREIGN KEY("catalogId") REFERENCES "dealer_catalogs"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "catalog_checks_catalogId_revision_idx" ON "catalog_checks"("catalogId","revision");
CREATE TABLE "catalog_sources" ("id" TEXT NOT NULL PRIMARY KEY,"catalogId" TEXT NOT NULL,"name" TEXT NOT NULL,"hash" TEXT NOT NULL,"size" INTEGER NOT NULL,"data" TEXT,"complete" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "catalog_sources_catalogId_fkey" FOREIGN KEY("catalogId") REFERENCES "dealer_catalogs"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "catalog_sources_catalogId_name_key" ON "catalog_sources"("catalogId","name");
CREATE TABLE "catalog_chunks" ("id" TEXT NOT NULL PRIMARY KEY,"sourceId" TEXT NOT NULL,"part" INTEGER NOT NULL,"data" TEXT NOT NULL,CONSTRAINT "catalog_chunks_sourceId_fkey" FOREIGN KEY("sourceId") REFERENCES "catalog_sources"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "catalog_chunks_sourceId_part_key" ON "catalog_chunks"("sourceId","part");
